import bruzem

def _to_number(value):
    """Convert a value to a numeric type (int or float) if possible."""
    if isinstance(value, (int, float)):
        return value
    try:
        # Try integer conversion first
        return int(value)
    except (ValueError, TypeError):
        try:
            # Fallback to float conversion
            return float(value)
        except (ValueError, TypeError):
            raise TypeError(f"Unable to convert {value!r} to a number.")

